import{_ as i,o as e,c as t,an as s}from"./chunks/framework.CliSN-dr.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"NicheMapper.jl","text":"Mechanistic niche modelling","tagline":"Can an organism complete its life cycle in a particular place and time, without overheating, desiccating or starving? The Julia successor to NicheMapR.","image":{"src":"/ThermoNiche.jpg","alt":"A lizard in thermal and water-balance colours against a desert landscape (Elia Pirtle)"},"actions":[{"theme":"brand","text":"The packages","link":"/packages"},{"theme":"alt","text":"View on Github","link":"https://github.com/BiophysicalEcology/NicheMapper.jl"},{"theme":"alt","text":"Architecture","link":"/architecture/mechanistic_niche_modelling_framework"}]},"features":[{"title":"🌦️ Microclimates","details":"Soil, surface and air conditions from <a class=\\"highlight-link\\">Microclimate.jl</a>, run over points and grids from any forcing data set with <a class=\\"highlight-link\\">MicroclimateMapper.jl</a>.","link":"/packages#Physical-environment"},{"title":"🌬️ Physics of the environment","details":"Properties of air and water from <a class=\\"highlight-link\\">FluidProperties.jl</a>, and clear-sky solar radiation from <a class=\\"highlight-link\\">SolarRadiation.jl</a>.","link":"/packages#Physical-environment"},{"title":"🔥 Heat and water exchange","details":"Body and leaf temperatures from <a class=\\"highlight-link\\">HeatExchange.jl</a>, for shapes and insulation from <a class=\\"highlight-link\\">BiophysicalGeometry.jl</a>.","link":"/packages#Organisms"},{"title":"🦎 Behaviour and physiology","details":"Thermoregulation and activity with <a class=\\"highlight-link\\">BiophysicalBehaviour.jl</a>, thermal performance with <a class=\\"highlight-link\\">ThermalPhysiology.jl</a>.","link":"/packages#Organisms"},{"title":"⚖️ Metabolism and scaling","details":"Dynamic Energy Budget life cycles with <a class=\\"highlight-link\\">DEBtool_J.jl</a>, and allometry with <a class=\\"highlight-link\\">BiologicalScaling.jl</a>.","link":"/packages#Metabolism"},{"title":"🗺️ Animals, plants and microbes","details":"The <a class=\\"highlight-link\\">AnimalMapper</a>, <a class=\\"highlight-link\\">PlantMapper</a> and <a class=\\"highlight-link\\">MicrobeMapper</a> packages (planned) put organisms into mapped microclimates.","link":"/packages#Mapper-packages"},{"title":"📏 Units, dispatch and speed","details":"Every package uses <a class=\\"highlight-link\\">Unitful.jl</a>, swaps sub-models by passing a type, and aims to be type-stable, non-allocating and differentiable.","link":"/architecture/extending_with_dispatch"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),l={name:"index.md"};function n(h,a,r,o,c,p){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h2 id="What-it-does" tabindex="-1">What it does <a class="header-anchor" href="#What-it-does" aria-label="Permalink to &quot;What it does {#What-it-does}&quot;">​</a></h2><p>Starting from the <a href="https://doi.org/10.1111/1365-2435.13829" target="_blank" rel="noreferrer">functional traits</a> of an organism, the packages compute the sequence of environments it experiences in a habitat, and whether that sequence lies inside or outside its niche. This integrates:</p><ul><li><p>the external exchange of heat and water, from <strong>biophysical ecology</strong>;</p></li><li><p>the internal processes of growth, development and reproduction, from <strong>metabolic theory</strong> (Dynamic Energy Budget theory);</p></li><li><p>the <strong>microclimates</strong> the organism is exposed to, from micrometeorology, soil physics and hydrology.</p></li></ul><p>See <a href="./background">History</a> for how this grew from a question about why desert iguanas change colour.</p><h2 id="How-to-install-NicheMapper.jl?" tabindex="-1">How to install NicheMapper.jl? <a class="header-anchor" href="#How-to-install-NicheMapper.jl?" aria-label="Permalink to &quot;How to install NicheMapper.jl? {#How-to-install-NicheMapper.jl?}&quot;">​</a></h2><p>NicheMapper.jl is a meta-package: installing it pulls in the whole ecosystem. It is not yet registered, so install it from GitHub:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/BiophysicalEcology/NicheMapper.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Each package can also be installed on its own; see <a href="./packages">The packages</a> for where to start for a given problem, and <a href="./nichemapr">For NicheMapR users</a> for where NicheMapR&#39;s functions now live.</p><h2 id="Status" tabindex="-1">Status <a class="header-anchor" href="#Status" aria-label="Permalink to &quot;Status {#Status}&quot;">​</a></h2><p>The physics and biology packages are in use; the Mapper packages for animals, plants and microbes are at the design stage. The <a href="./architecture/mechanistic_niche_modelling_framework">Architecture overview</a> sets out the design, the use cases it serves and the build order.</p>`,10)])])}const k=i(l,[["render",n]]);export{d as __pageData,k as default};
